package net.minecraft.util;public class Vec3{public double xCoord,yCoord,zCoord;public static Vec3 createVectorHelper(double x,double y,double z){var v=new Vec3();v.xCoord=x;v.yCoord=y;v.zCoord=z;return v;}private void set(net.minecraft.world.phys.Vec3 v){xCoord=v.x;yCoord=v.y;zCoord=v.z;}public void rotateAroundX(float a){set(new net.minecraft.world.phys.Vec3(xCoord,yCoord,zCoord).xRot(a));}public void rotateAroundY(float a){set(new net.minecraft.world.phys.Vec3(xCoord,yCoord,zCoord).yRot(a));}public void rotateAroundZ(float a){set(new net.minecraft.world.phys.Vec3(xCoord,yCoord,zCoord).zRot(a));}public Vec3 normalize(){var v=new net.minecraft.world.phys.Vec3(xCoord,yCoord,zCoord).normalize();return createVectorHelper(v.x,v.y,v.z);}}
